export type Memory = {
  save(options: {
    transcript?: string;
    catchUp?: boolean;
    cwd?: string;
    detach?: boolean;
    log?: boolean;
  }): Promise<unknown>;
  search(options: {
    query: string;
    limit?: number;
    since?: string;
    project?: string;
  }): Promise<unknown>;
  show(options: {
    session: string;
    full?: boolean;
    lines?: string;
  }): Promise<unknown>;
  list(options: {
    since?: string;
    project?: string;
    unsaved?: boolean;
    limit?: number;
  }): Promise<unknown>;
  blobPut(options: {
    file: string;
  }): Promise<unknown>;
  blobPath(options: {
    sha256: string;
  }): Promise<unknown>;
  note(options: {
    text?: string;
    expires?: number;
    keep?: boolean;
    global?: boolean;
    drop?: string;
  }): Promise<unknown>;
  notes(options: {
    all?: boolean;
  }): Promise<unknown>;
  orient(options: {
    cwd?: string;
  }): Promise<unknown>;
  doctor(): Promise<unknown>;
};

declare module 'claude-code' {
  interface EngineInterface {
    memory: Memory;
  }
}
